import assert from 'node:assert/strict';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { ROOT } from './helpers.js';

const EXT_DIR = join(ROOT, 'extension');

function* walk(dir) {
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) yield* walk(p);
    else yield p;
  }
}

test('扩展：源码无任何出站请求 API / 远程 URL', () => {
  const bannedApi = /\b(fetch|XMLHttpRequest|WebSocket|EventSource|sendBeacon)\b/;
  const bannedUrl = /https?:\/\//;
  for (const file of walk(EXT_DIR)) {
    if (!/\.js$/.test(file)) continue; // JS 源码：禁止任何网络 API 与硬编码 URL
    const src = readFileSync(file, 'utf8');
    assert.ok(!bannedApi.test(src), `${file} 含出站请求 API`);
    assert.ok(!bannedUrl.test(src), `${file} 含硬编码远程 URL`);
  }
});

test('扩展：manifest 权限最小化且 CSP 禁止远程代码', () => {
  const man = JSON.parse(readFileSync(join(EXT_DIR, 'manifest.json'), 'utf8'));
  assert.equal(man.manifest_version, 3);
  assert.deepEqual(man.permissions ?? [], [], '不应声明任何权限');
  assert.deepEqual(man.host_permissions ?? [], [], '不应声明主机权限');
  const csp = man.content_security_policy?.extension_pages ?? '';
  assert.ok(!csp.includes('http'), 'CSP 不应允许远程来源');
});

