    const rect = el.getBoundingClientRect();
    const evt = new MouseEvent(type, {
      bubbles: true, cancelable: true, view: window,
      clientX: rect.left + x, clientY: rect.top + y,
      button: 0, buttons: type === 'mouseup' ? 0 : 1,
    });
    el.dispatchEvent(evt);
  }

  async function solveSlider(widget) {
    const canvas = widget.querySelector('canvas');
    const handle = widget.querySelector('[data-role="handle"]');
    const result = core.locateGap(canvasImage(canvas));
    if (result.action !== 'solve') {
      setStatus(widget, `滑块：低置信度(${result.confidence.toFixed(2)})，跳过/人工`, false);
      return;
    }
    const handleX = parseFloat(handle.dataset.x || '0');
    const distance = result.x - handleX;
    const traj = core.generateTrajectory(distance);
    const stats = core.trajectoryStats(traj);
    setStatus(widget, `滑块：缺口 x=${result.x} 置信度=${result.confidence.toFixed(2)} ` +
      `拖动 ${traj.points.length} 步/${stats.duration}ms 过冲=${stats.hasOvershoot}`);
    const y = handle.offsetHeight / 2;
    dispatchMouse(handle, 'mousedown', handleX + 4, y);
    for (const p of traj.points) {
      await new Promise(r => setTimeout(r, Math.max(4, p.t - (traj.points[traj.points.indexOf(p) - 1]?.t ?? 0))));
      dispatchMouse(document, 'mousemove', handleX + p.x, y + p.y);
    }
    dispatchMouse(document, 'mouseup', handleX + distance, y);
  }

  function solveChars(widget) {
    const canvas = widget.querySelector('canvas');
    const input = widget.querySelector('input');
    const button = widget.querySelector('button[data-role="verify"]');
    const result = core.recognizeChars(canvasImage(canvas));
    if (result.action !== 'solve') {
      setStatus(widget, `字符：低置信度(${(result.confidence ?? 0).toFixed(2)})，跳过/人工`, false);
      return;
    }
    input.value = result.text;
    setStatus(widget, `字符：识别为 "${result.text}" 置信度=${result.confidence.toFixed(2)}`);
    button.click();
  }

