export function recognizeChars(img, options = {}) {
  const opts = { ...CHAR_DEFAULTS, ...options };
  const { width, height } = img;
  const gray = toGray(img);
  const bits = extractGlyphBits(gray, width, height, opts.minComponentSize);
  const segs = segmentAndRecognize(bits, width, height, opts);
  if (!segs || segs.length === 0) {
    return { action: 'skip', reason: 'no-glyphs', confidence: 0, text: '' };
  }
  const text = segs.map(s => s.ch).join('');
  const minConf = Math.min(...segs.map(s => s.conf));
  const avgCost = segs.reduce((a, s) => a + s.cost, 0) / segs.length;
  // 综合置信度：间隔为主，绝对匹配质量兜底（匹配差则降权）
  const confidence = Math.max(0, Math.min(1, minConf * (1 - Math.min(0.7, avgCost))));
  if (confidence < opts.confidenceThreshold) {
    return { action: 'skip', reason: 'low-confidence', confidence, text, chars: segs };
  }
  return { action: 'solve', text, confidence, chars: segs };
}
