/**
 * 图片字符识别（升级版）：纯函数，全程本地（内置 5x7 点阵小模型，无外部 OCR）。
 * 难点对策：
 *  - 旋转：模板按多角度预渲染（-24°~24°），匹配时取最优；
 *  - 扭曲/噪点：归一化覆盖网格 + 非对称软匹配（缺笔罚重、多墨罚轻）；
 *  - 粘连：列投影候选边界 + 动态规划分割（宽度约束，允许无空白列处强制切分）；
 *  - 大小写混淆：引入"字高占行高比"尺寸特征（c/C、o/O 等靠高度占比区分）；
 *  - 干扰线：连通域去噪 + 多墨轻罚。
 * 置信度 = 逐字最优/次优间隔的最小值；低于阈值输出 skip，不硬猜。
 */
import { toGray, binarize } from './image.js';
import { FONT, CHARSET } from './font.js';

export const CHAR_DEFAULTS = {
  confidenceThreshold: 0.32,
  minComponentSize: 8,
  maxChars: 6,
  minChars: 3,
};

const GW = 10, GH = 14;           // 归一化网格（对应 5x7 字模，2 倍超采样）
const ANGLES = [-24, -16, -8, 0, 8, 16, 24];

/** 连通域标记（8 邻域）。 */
function connectedComponents(bits, width, height) {
  const labels = new Int32Array(width * height).fill(-1);
  const sizes = [];
  const stack = [];
  for (let i = 0; i < bits.length; i++) {
    if (!bits[i] || labels[i] >= 0) continue;
    const id = sizes.length;
    let size = 0;
    stack.push(i);
    labels[i] = id;
    while (stack.length) {
      const p = stack.pop();
      size++;
      const px = p % width, py = (p / width) | 0;
      for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
        if (!dx && !dy) continue;
        const nx = px + dx, ny = py + dy;
        if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
        const ni = ny * width + nx;
        if (bits[ni] && labels[ni] < 0) { labels[ni] = id; stack.push(ni); }
      }
    }
    sizes.push(size);
  }
  return { labels, sizes };
}

/** 暗色笔画前景 + 去除微小连通域（噪点）。 */
function extractGlyphBits(gray, width, height, minSize) {
  const { bits } = binarize(gray, width, height, true); // 暗=前景
  const { labels, sizes } = connectedComponents(bits, width, height);
  const keep = sizes.map(s => s >= minSize);
  const out = new Uint8Array(width * height);
  for (let i = 0; i < bits.length; i++) {
    if (bits[i] && keep[labels[i]]) out[i] = 1;
  }
  return out;
}

/** 把 5x7 字模按角度旋转渲染到 GWxGH 覆盖网格（绕中心，双线性）。 */
function renderTemplate(rows, angleDeg) {
  const grid = new Float32Array(GW * GH);
  const rad = angleDeg * Math.PI / 180;
  const cos = Math.cos(rad), sin = Math.sin(rad);
  const cx = 2, cy = 3; // 5x7 中心
  for (let gy = 0; gy < GH; gy++) {
    for (let gx = 0; gx < GW; gx++) {
      const tx = (gx + 0.5) / 2 - 0.5 - cx; // 网格坐标 -> 字模坐标
      const ty = (gy + 0.5) / 2 - 0.5 - cy;
      const sx = cos * tx + sin * ty + cx;
      const sy = -sin * tx + cos * ty + cy;
      // 双线性采样 5x7 字模
      const x0 = Math.floor(sx), y0 = Math.floor(sy);
      const fx = sx - x0, fy = sy - y0;
      let v = 0;
      for (let dy = 0; dy <= 1; dy++) for (let dx = 0; dx <= 1; dx++) {
        const yy = y0 + dy, xx = x0 + dx;
        if (yy < 0 || yy > 6 || xx < 0 || xx > 4) continue;
        const w = (dx ? fx : 1 - fx) * (dy ? fy : 1 - fy);
        if (rows[yy][xx] === '1') v += w;
      }
      grid[gy * GW + gx] = v;
    }
  }
  return grid;
}

let TPL_CACHE = null;
/** 预渲染全部 字符x角度 模板（惰性缓存）。 */
function templates() {
  if (TPL_CACHE) return TPL_CACHE;
  TPL_CACHE = [];
  for (const ch of CHARSET) {
    const rows = FONT[ch];
    let top = 7, bot = -1;
    for (let y = 0; y < 7; y++) if (rows[y].includes('1')) { top = Math.min(top, y); bot = Math.max(bot, y); }
    const hFrac = (bot - top + 1) / 7; // 字高占行高比（区分大小写的尺寸特征）
    for (const a of ANGLES) {
      const grid = renderTemplate(rows, a);
      let ink = 0;
      for (let i = 0; i < grid.length; i++) ink += grid[i];
      TPL_CACHE.push({ ch, grid, ink, hFrac });
    }
  }
  return TPL_CACHE;
}

/** 区域二值图 -> GWxGH 覆盖网格（按自身包围盒归一化）。 */
function normalizeRegion(bits, width, x0, y0, x1, y1) {
  const grid = new Float32Array(GW * GH);
  const w = x1 - x0 + 1, h = y1 - y0 + 1;
  for (let gy = 0; gy < GH; gy++) {
    for (let gx = 0; gx < GW; gx++) {
      const sx0 = x0 + (gx * w) / GW, sx1 = x0 + ((gx + 1) * w) / GW;
      const sy0 = y0 + (gy * h) / GH, sy1 = y0 + ((gy + 1) * h) / GH;
      // 区域可能非整数，按覆盖近似：采样 2x2 子点
      let on = 0, tot = 0;
      for (let sy = sy0; sy < sy1; sy += Math.max(1, (sy1 - sy0) / 2)) {
        for (let sx = sx0; sx < sx1; sx += Math.max(1, (sx1 - sx0) / 2)) {
          const xx = Math.min(width - 1, Math.round(sx));
          tot++;
          // bits 按行存储需要 height，此处调用方保证行列有效
          if (bits[Math.round(sy) * width + xx]) on++;
        }
      }
      grid[gy * GW + gx] = tot ? on / tot : 0;
    }
  }
  return grid;
}

/** 非对称软匹配：缺笔罚 1、多墨罚 0.45，按模板墨量归一化；附加字高比惩罚。 */
function matchSegment(grid, segHFrac) {
  let best = null, second = null;
  for (const t of templates()) {
    let miss = 0, extra = 0;
    for (let i = 0; i < grid.length; i++) {
      const tv = t.grid[i], sv = grid[i];
      if (tv > sv) miss += tv - sv; else extra += sv - tv;
    }
    let score = (miss + 0.45 * extra) / Math.max(1, t.ink);
    score += 0.9 * Math.abs(segHFrac - t.hFrac);
    if (!best || score < best.score) { second = best; best = { ch: t.ch, score }; }
    else if (!second || score < second.score) second = { ch: t.ch, score };
  }
  return { best, second };
