/** 动态规划分割：候选边界间枚举分段，宽度约束 + 匹配代价最小。 */
function segmentAndRecognize(bits, width, height, opts) {
  const colInk = new Float64Array(width);
  const rowInk = new Float64Array(height);
  for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
    if (bits[y * width + x]) { colInk[x]++; rowInk[y]++; }
  }
  let xStart = -1, xEnd = -1;
  for (let x = 0; x < width; x++) if (colInk[x] > 0) { if (xStart < 0) xStart = x; xEnd = x; }
  if (xStart < 0) return null;
