  const sm = new Float64Array(width);
  for (let x = 0; x < width; x++) {
    const a = energy[Math.max(0, x - 1)], b = energy[x], c = energy[Math.min(width - 1, x + 1)];
    sm[x] = (a + 2 * b + c) / 4;
