{"cmd": "apply_patch <<'EOF'
*** Begin Patch
*** Update File: core/chars.js
@@
-const GW = 10, GH = 14;           // 归一化网格（对应 5x7 字模，2 倍超采样）
+const GW = 12, GH = 16;           // 归一化网格（对应 5x7 字模，超采样）
@@
-/** 区域二值图 -> GWxGH 覆盖网格（按自身包围盒归一化）。 */
-function normalizeRegion(bits, width, height, x0, y0, x1, y1) {
+/** 区域灰度 -> GWxGH 墨迹网格（按自身包围盒归一化，双线性采样）。
 *  直接用灰度而非二值，保留抗锯齿/模糊信息；干扰线（中灰）映射为弱墨迹。 */
+function normalizeRegion(gray, width, height, x0, y0, x1, y1) {
   const grid = new Float32Array(GW * GH);
   const w = x1 - x0 + 1, h = y1 - y0 + 1;
   for (let gy = 0; gy < GH; gy++) {
     for (let gx = 0; gx < GW; gx++) {
-      const sx0 = x0 + (gx * w) / GW, sx1 = x0 + ((gx + 1) * w) / GW;
-      const sy0 = y0 + (gy * h) / GH, sy1 = y0 + ((gy + 1) * h) / GH;
-      // 区域可能非整数，按覆盖近似：采样 2x2 子点
-      let on = 0, tot = 0;
-      for (let sy = sy0; sy < sy1; sy += Math.max(1, (sy1 - sy0) / 2)) {
-        for (let sx = sx0; sx < sx1; sx += Math.max(1, (sx1 - sx0) / 2)) {
-          const xx = Math.min(width - 1, Math.round(sx));
-          const yy = Math.min(height - 1, Math.max(0, Math.round(sy)));
-          tot++;
-          if (bits[yy * width + xx]) on++;
-        }
-      }
-      grid[gy * GW + gx] = tot ? on / tot : 0;
+      // 2x2 子采样取平均灰度 -> 墨迹强度
+      let v = 0;
+      for (let sy = 0.25; sy < 1; sy += 0.5) {
+        for (let sx = 0.25; sx < 1; sx += 0.5) {
+          const px = Math.min(width - 1, x0 + ((gx + sx) * w) / GW);
+          const py = Math.min(height - 1, y0 + ((gy + sy) * h) / GH);
+          const g = gray[Math.round(py) * width + Math.round(px)];
+          v += Math.max(0, Math.min(1, (190 - g) / 170));
+        }
+      }
+      grid[gy * GW + gx] = v / 4;
     }
   }
   return grid;
 }
*** End Patch
EOF
grep -n 'normalizeRegion(bits' core/chars.js"}

