payload.arguments:
{"cmd": "python3 - <<'EOF'
p = 'core/chars.js'
src = open(p).read()
old = '''  // 旋转后墨盒宽高比（识别侧与生成侧旋转一致，特征自洽）
  let t0 = GH, t1 = -1, l0 = GW, l1 = -1;
  for (let gy = 0; gy < GH; gy++) for (let gx = 0; gx < GW; gx++) {
    if (grid[gy * GW + gx] > 0.15) {
      if (gy < t0) t0 = gy; if (gy > t1) t1 = gy;
      if (gx < l0) l0 = gx; if (gx > l1) l1 = gx;
    }
  }
  const aspect = (l1 - l0 + 1) / Math.max(1, t1 - t0 + 1);
  return { grid, aspect };'''
new = '''  // 旋转后墨盒宽高比（解析式，字模单位；识别侧 charW=lineH*5/7 时 w/h 与之同尺度）
  const c = Math.abs(cos), s = Math.abs(sin);
  const aspect = (bw * c + bh * s) / (bw * s + bh * c);
  return { grid, aspect };'''
assert old in src; src = src.replace(old, new)
src = src.replace('score += 0.7 * Math.abs(segHFrac - t.hFrac);',
                  'score += 0.8 * Math.abs(segHFrac - t.hFrac);')
src = src.replace('score += 1.4 * Math.abs(Math.log(Math.max(0.2, segAspect) / Math.max(0.2, t.aspect)));',
                  'score += 1.0 * Math.abs(Math.log(Math.max(0.2, segAspect) / Math.max(0.2, t.aspect)));')
open(p, 'w').write(src)
print('ok')
EOF
node /tmp/cal.mjs 2>&1 | head -4"}

