{"cmd": "python3 - <<'EOF'
p = 'core/chars.js'
src = open(p).read()

# 1) 模板缓存：增加 DT 与二值墨量
old = '''    for (const a of ANGLES) {
      const { grid, aspect } = renderTemplate(rows, a);
      let ink = 0;
      for (let i = 0; i < grid.length; i++) ink += grid[i];
      TPL_CACHE.push({ ch, grid, ink, hFrac, aspect });
    }'''
new = '''    for (const a of ANGLES) {
      const { grid, aspect } = renderTemplate(rows, a);
      let ink = 0;
      for (let i = 0; i < grid.length; i++) ink += grid[i];
      TPL_CACHE.push({ ch, grid, ink, hFrac, aspect, dt: distanceTransform(grid, GW, GH) });
    }'''
assert old in src; src = src.replace(old, new)

# 2) 距离变换工具（两趟 chamfer，近似欧氏距离，单位=格）
old = '''let TPL_CACHE = null;'''
new = '''/** 近似距离变换：每个格子到最近墨迹格（ink>0.35）的距离。 */
function distanceTransform(grid, w, h) {
  const INF = 1e6;
  const dt = new Float32Array(w * h);
  for (let i = 0; i < w * h; i++) dt[i] = grid[i] > 0.35 ? 0 : INF;
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const i = y * w + x;
    if (x > 0) dt[i] = Math.min(dt[i], dt[i - 1] + 1);
    if (y > 0) {
      dt[i] = Math.min(dt[i], dt[i - w] + 1);
      if (x > 0) dt[i] = Math.min(dt[i], dt[i - w - 1] + 1.414);
      if (x < w - 1) dt[i] = Math.min(dt[i], dt[i - w + 1] + 1.414);
    }
  }
  for (let y = h - 1; y >= 0; y--) for (let x = w - 1; x >= 0; x--) {
    const i = y * w + x;
    if (x < w - 1) dt[i] = Math.min(dt[i], dt[i + 1] + 1);
    if (y < h - 1) {
      dt[i] = Math.min(dt[i], dt[i + w] + 1);
      if (x < w - 1) dt[i] = Math.min(dt[i], dt[i + w + 1] + 1.414);
      if (x > 0) dt[i] = Math.min(dt[i], dt[i + w - 1] + 1.414);
    }
  }
  return dt;
}

let TPL_CACHE = null;'''
assert old in src; src = src.replace(old, new)

# 3) matchSegment 改为对称 chamfer
old_start = src.index('/** 非对称软匹配')
old_end = src.index('/** 动态规划分割')
new_match = '''/** 对称 chamfer 匹配：墨迹点集到模板/模板到墨迹的双向平均距离，
 *  对波浪扭曲引起的 1~2 格笔画位移天然鲁棒；附加字高比/宽高比惩罚区分大小写。 */
function matchSegment(grid, segHFrac, segAspect) {
  const segDT = distanceTransform(grid, GW, GH);
  let segInk = 0;
  for (let i = 0; i < grid.length; i++) segInk += grid[i];
  segInk = Math.max(1, segInk);
  const perChar = new Map();
  for (const t of templates()) {
    let d1 = 0, d2 = 0;
    for (let i = 0; i < grid.length; i++) {
      d1 += grid[i] * t.dt[i];
      d2 += t.grid[i] * segDT[i];
    }
    let score = 0.5 * (d1 / segInk + d2 / t.ink) / 2.2;
    score += 0.8 * Math.abs(segHFrac - t.hFrac);
    score += 1.0 * Math.abs(Math.log(Math.max(0.2, segAspect) / Math.max(0.2, t.aspect)));
    const cur = perChar.get(t.ch);
    if (cur === undefined || score < cur) perChar.set(t.ch, score);
  }
  let best = null, second = null;
  for (const [ch, score] of perChar) {
    if (!best || score < best.score) { second = best; best = { ch, score }; }
    else if (!second || score < second.score) second = { ch, score };
  }
  return { best, second };
}

'''
src = src[:old_start] + new_match + src[old_end:]
open(p,'w').write(src)
print('ok')
EOF
