new = '''/** 近似距离变换：每个格子到最近墨迹格（ink>0.35）的距离。 */
function distanceTransform(grid, w, h) {
  const INF = 1e6;
  const dt = new Float32Array(w * h);
  for (let i = 0; i < w * h; i++) dt[i] = grid[i] > 0.35 ? 0 : INF;
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const i = y * w + x;
    if (x > 0) dt[i] = Math.min(dt[i], dt[i - 1] + 1);
    if (y > 0) {
      dt[i] = Math.min(dt[i], dt[i - w] + 1);
      if (x > 0) dt[i] = Math.min(dt[i], dt[i - w - 1] + 1.414);
      if (x < w - 1) dt[i] = Math.min(dt[i], dt[i - w + 1] + 1.414);
    }
  }
  for (let y = h - 1; y >= 0; y--) for (let x = w - 1; x >= 0; x--) {
    const i = y * w + x;
    if (x < w - 1) dt[i] = Math.min(dt[i], dt[i + 1] + 1);
    if (y < h - 1) {
      dt[i] = Math.min(dt[i], dt[i + w] + 1);
      if (x < w - 1) dt[i] = Math.min(dt[i], dt[i + w + 1] + 1.414);
      if (x > 0) dt[i] = Math.min(dt[i], dt[i + w - 1] + 1.414);
    }
  }
  return dt;
}

let TPL_CACHE = null;'''
