# 3) matchSegment 改为对称 chamfer
old_start = src.index('/** 非对称软匹配')
old_end = src.index('/** 动态规划分割')
new_match = '''/** 对称 chamfer 匹配：墨迹点集到模板/模板到墨迹的双向平均距离，
 *  对波浪扭曲引起的 1~2 格笔画位移天然鲁棒；附加字高比/宽高比惩罚区分大小写。 */
function matchSegment(grid, segHFrac, segAspect) {
  const segDT = distanceTransform(grid, GW, GH);
  let segInk = 0;
  for (let i = 0; i < grid.length; i++) segInk += grid[i];
  segInk = Math.max(1, segInk);
  const perChar = new Map();
  for (const t of templates()) {
    let d1 = 0, d2 = 0;
    for (let i = 0; i < grid.length; i++) {
      d1 += grid[i] * t.dt[i];
      d2 += t.grid[i] * segDT[i];
    }
    let score = 0.5 * (d1 / segInk + d2 / t.ink) / 2.2;
    score += 0.8 * Math.abs(segHFrac - t.hFrac);
    score += 1.0 * Math.abs(Math.log(Math.max(0.2, segAspect) / Math.max(0.2, t.aspect)));
    const cur = perChar.get(t.ch);
    if (cur === undefined || score < cur) perChar.set(t.ch, score);
  }
  let best = null, second = null;
  for (const [ch, score] of perChar) {
    if (!best || score < best.score) { second = best; best = { ch, score }; }
    else if (!second || score < second.score) second = { ch, score };
  }
  return { best, second };
}

'''
src = src[:old_start] + new_match + src[old_end:]
