{"cmd": "python3 - <<'EOF'
p = 'core/chars.js'
src = open(p).read()

src = src.replace("import { TEMPLATES } from './templates.js';",
                  "import { TEMPLATES, LINE_OVER_ADVANCE } from './templates.js';")
src = src.replace("TPL_CACHE.push({ ch, grid, ink, aspect: t.r, dt: distanceTransform(grid, GW, GH) });",
                  "TPL_CACHE.push({ ch, grid, ink, aspect: t.r, hFrac: t.h, dt: distanceTransform(grid, GW, GH) });")

src = src.replace('''function matchSegment(grid, segAspect) {''',
'''function matchSegment(grid, segAspect, segHFrac = null) {''')
src = src.replace('''    let score = 0.5 * (d1 / segInk + d2 / t.ink) / 2.2;
    score += 1.2 * Math.max(0, Math.abs(Math.log(Math.max(0.2, segAspect) / Math.max(0.2, t.aspect))) - 0.08);''',
'''    let score = 0.5 * (d1 / segInk + d2 / t.ink) / 2.2;
    score += 1.2 * Math.max(0, Math.abs(Math.log(Math.max(0.2, segAspect) / Math.max(0.2, t.aspect))) - 0.08);
    if (segHFrac !== null) {
      score += 1.0 * Math.max(0, Math.abs(segHFrac - t.hFrac) - 0.06);
    }''')

# seg 对象记录 y0/y1
src = src.replace("segScore.set(i * 4096 + j, { x0: xa, x1: xb, ch: m.best.ch,",
                  "segScore.set(i * 4096 + j, { x0: xa, x1: xb, y0, y1, ch: m.best.ch,")
src = src.replace("segs.push({ x0: xa, x1: xb, ch: m.best.ch,",
                  "segs.push({ x0: xa, x1: xb, y0, y1, ch: m.best.ch,")

# 两遍打分：分割后利用等宽字距反推行高，带 hFrac 重打分
old = '''  const segs = segmentAndRecognize(gray, bits, width, height, opts)
    ?? fallbackSegment(gray, bits, width, height, opts);
  if (!segs || segs.length === 0) {
    return { action: 'skip', reason: 'no-glyphs', confidence: 0, text: '' };
  }'''
new = '''  const segs = segmentAndRecognize(gray, bits, width, height, opts)
    ?? fallbackSegment(gray, bits, width, height, opts);
  if (!segs || segs.length === 0) {
    return { action: 'skip', reason: 'no-glyphs', confidence: 0, text: '' };
  }
  // 第二遍：等宽字体字距恒定 -> 由实测字距反推行高，引入绝对字高特征重打分
  const span = segs[segs.length - 1].x1 - segs[0].x0 + 1;
  const lineH = (span / segs.length) * LINE_OVER_ADVANCE;
  for (const s of segs) {
    const grid = normalizeRegion(gray, width, height, s.x0, s.y0, s.x1, s.y1);
    const segHFrac = (s.y1 - s.y0 + 1) / lineH;
    const m = matchSegment(grid, (s.x1 - s.x0 + 1) / (s.y1 - s.y0 + 1), segHFrac);
    s.ch = m.best.ch;
    s.cost = m.best.score;
    s.conf = Math.max(0, (m.second.score - m.best.score) / Math.max(0.05, m.second.score));
  }'''
assert old in src; src = src.replace(old, new)
open(p,'w').write(src)
print('ok')
EOF
