    score += 1.2 * Math.max(0, Math.abs(Math.log(Math.max(0.2, segAspect) / Math.max(0.2, t.aspect))) - 0.08);
    if (segHFrac !== null) {
      score += 1.0 * Math.max(0, Math.abs(segHFrac - t.hFrac) - 0.06);
    }''')

