src = src.replace("segs.push({ x0: xa, x1: xb, ch: m.best.ch,",
                  "segs.push({ x0: xa, x1: xb, y0, y1, ch: m.best.ch,")

# 两遍打分：分割后利用等宽字距反推行高，带 hFrac 重打分
old = '''  const segs = segmentAndRecognize(gray, bits, width, height, opts)
    ?? fallbackSegment(gray, bits, width, height, opts);
  if (!segs || segs.length === 0) {
    return { action: 'skip', reason: 'no-glyphs', confidence: 0, text: '' };
