new = '''  const segs = segmentAndRecognize(gray, bits, width, height, opts)
    ?? fallbackSegment(gray, bits, width, height, opts);
  if (!segs || segs.length === 0) {
    return { action: 'skip', reason: 'no-glyphs', confidence: 0, text: '' };
  }
