function refineSegments(segs, gray, bits, width, height, opts) {
  const scoreRegion = (x0, x1) => {
    let y0 = height, y1 = 0, ink = 0;
    for (let x = x0; x <= x1; x++) for (let y = 0; y < height; y++) {
      if (bits[y * width + x]) { ink++; if (y < y0) y0 = y; if (y > y1) y1 = y; }
    }
    if (ink < opts.minComponentSize) return null;
    const grid = normalizeRegion(gray, width, height, x0, y0, x1, y1);
    const m = matchSegment(grid, (x1 - x0 + 1) / (y1 - y0 + 1));
    return { y0, y1, ch: m.best.ch, cost: m.best.score,
             conf: Math.max(0, (m.second.score - m.best.score) / Math.max(0.05, m.second.score)) };
  };
  // 合并：i 与 i+1 合并代价 < 两段代价和 - 边际
  for (let i = 0; i < segs.length - 1 && segs.length > opts.minChars;) {
    const a = segs[i], b = segs[i + 1];
    const merged = scoreRegion(a.x0, b.x1);
    if (merged && merged.cost < a.cost + b.cost - 0.12) {
      segs.splice(i, 2, { x0: a.x0, x1: b.x1, ...merged });
    } else i++;
  }
  // 拆分：过宽段在中间低谷切开更优则拆
  for (let i = 0; i < segs.length && segs.length < opts.maxChars;) {
    const s = segs[i];
    const w = s.x1 - s.x0 + 1;
    const colInk = [];
    for (let x = s.x0; x <= s.x1; x++) {
      let c = 0;
      for (let y = 0; y < height; y++) if (bits[y * width + x]) c++;
      colInk.push(c);
    }
    let bestGain = 0.12, bestCut = -1, bestL = null, bestR = null;
    for (let cx = s.x0 + Math.floor(w * 0.3); cx <= s.x0 + Math.ceil(w * 0.7); cx++) {
      const l = scoreRegion(s.x0, cx), r = scoreRegion(cx + 1, s.x1);
      if (!l || !r) continue;
      const gain = s.cost - (l.cost + r.cost);
      if (gain > bestGain) { bestGain = gain; bestCut = cx; bestL = l; bestR = r; }
    }
    if (bestCut > 0) {
      segs.splice(i, 1,
        { x0: s.x0, x1: bestCut, ...bestL },
        { x0: bestCut + 1, x1: s.x1, ...bestR });
    } else i++;
  }
}

