      segs.splice(i, 2, { x0: a.x0, x1: b.x1, ...merged });
    } else i++;
  }
  // 拆分：过宽段在中间低谷切开更优则拆
  for (let i = 0; i < segs.length && segs.length < opts.maxChars;) {
    const s = segs[i];
    const w = s.x1 - s.x0 + 1;
    const colInk = [];
    for (let x = s.x0; x <= s.x1; x++) {
      let c = 0;
      for (let y = 0; y < height; y++) if (bits[y * width + x]) c++;
      colInk.push(c);
    }
    let bestGain = 0.12, bestCut = -1, bestL = null, bestR = null;
    for (let cx = s.x0 + Math.floor(w * 0.3); cx <= s.x0 + Math.ceil(w * 0.7); cx++) {
      const l = scoreRegion(s.x0, cx), r = scoreRegion(cx + 1, s.x1);
      if (!l || !r) continue;
      const gain = s.cost - (l.cost + r.cost);
      if (gain > bestGain) { bestGain = gain; bestCut = cx; bestL = l; bestR = r; }
    }
    if (bestCut > 0) {
      segs.splice(i, 1,
        { x0: s.x0, x1: bestCut, ...bestL },
        { x0: bestCut + 1, x1: s.x1, ...bestR });
    } else i++;
  }
}

