{"cmd": "python3 - <<'EOF'
p = 'core/chars.js'
src = open(p).read()

# 1) 模板缓存带角度
src = src.replace("TPL_CACHE.push({ ch, grid, ink, aspect: t.r, hFrac: t.h, dt: distanceTransform(grid, GW, GH) });",
                  "TPL_CACHE.push({ ch, angle: t.a, grid, ink, aspect: t.r, hFrac: t.h, dt: distanceTransform(grid, GW, GH) });")

# 2) matchSegment 返回角度，支持角度过滤
src = src.replace('''function matchSegment(grid, segAspect, segHFrac = null) {''',
'''function matchSegment(grid, segAspect, segHFrac = null, angle0Only = false) {''')
src = src.replace('''  const perChar = new Map();
  for (const t of templates()) {
    let d1 = 0, d2 = 0;''',
'''  const perChar = new Map();
  const perCharAngle = new Map();
  for (const t of templates()) {
    if (angle0Only && Math.abs(t.angle) > 3) continue;
    let d1 = 0, d2 = 0;''')
src = src.replace('''    const cur = perChar.get(t.ch);
    if (cur === undefined || score < cur) perChar.set(t.ch, score);
  }
  let best = null, second = null;
  for (const [ch, score] of perChar) {
    if (!best || score < best.score) { second = best; best = { ch, score }; }
    else if (!second || score < second.score) second = { ch, score };
  }
  return { best, second };
}''',
'''    const cur = perChar.get(t.ch);
    if (cur === undefined || score < cur) { perChar.set(t.ch, score); perCharAngle.set(t.ch, t.angle); }
  }
  let best = null, second = null;
  for (const [ch, score] of perChar) {
    if (!best || score < best.score) { second = best; best = { ch, score }; }
    else if (!second || score < second.score) second = { ch, score };
  }
  return { best: { ...best, angle: perCharAngle.get(best.ch) }, second };
}''')

# 3) 去旋转工具 + 重写第二遍打分
old = '''  // 第二遍：等宽字体字距恒定 -> 由实测字距反推行高，引入绝对字高特征重打分；
  // 行高在 ±12% 内自校准（字距测量有噪声），取总匹配代价最小的档位。
  const span = segs[segs.length - 1].x1 - segs[0].x0 + 1;
  const baseLineH = (span / segs.length) * LINE_OVER_ADVANCE;
  const grids = segs.map(s => normalizeRegion(gray, width, height, s.x0, s.y0, s.x1, s.y1));
  let bestPass = null;
  for (const scale of [0.88, 0.94, 1.0, 1.06, 1.12]) {
    const lineH = baseLineH * scale;
    let total = 0;
    const pass = segs.map((s, i) => {
      const segHFrac = (s.y1 - s.y0 + 1) / lineH;
      const m = matchSegment(grids[i], (s.x1 - s.x0 + 1) / (s.y1 - s.y0 + 1), segHFrac);
      total += m.best.score;
      return m;
    });
    if (!bestPass || total < bestPass.total) bestPass = { total, pass };
  }
  segs.forEach((s, i) => {
    const m = bestPass.pass[i];
    s.ch = m.best.ch;
    s.cost = m.best.score;
    s.conf = Math.max(0, (m.second.score - m.best.score) / Math.max(0.05, m.second.score));
  });'''
new = '''  // 第二遍：先去旋转（用第一遍估计的角度），再在 0° 模板族上重打分。
  // 去旋转后字高测量无旋转膨胀，大小写可可靠区分；行高由等宽字距反推并自校准。
  const span = segs[segs.length - 1].x1 - segs[0].x0 + 1;
  const baseLineH = (span / segs.length) * LINE_OVER_ADVANCE;
  const prepared = segs.map(s => {
    const grid0 = normalizeRegion(gray, width, height, s.x0, s.y0, s.x1, s.y1);
    const m1 = matchSegment(grid0, (s.x1 - s.x0 + 1) / (s.y1 - s.y0 + 1), null);
    return derotatePatch(gray, width, height, s, m1.best.angle);
  });
  let bestPass = null;
  for (const scale of [0.88, 0.94, 1.0, 1.06, 1.12]) {
    const lineH = baseLineH * scale;
    let total = 0;
    const pass = prepared.map(p => {
      const m = matchSegment(p.grid, p.aspect, p.inkH / lineH, true);
      total += m.best.score;
      return m;
    });
    if (!bestPass || total < bestPass.total) bestPass = { total, pass };
  }
  segs.forEach((s, i) => {
    const m = bestPass.pass[i];
    s.ch = m.best.ch;
    s.cost = m.best.score;
    s.conf = Math.max(0, (m.second.score - m.best.score) / Math.max(0.05, m.second.score));
  });'''
assert old in src; src = src.replace(old, new)

# 4) derotatePatch 实现（插在 refineSegments 前）
old = '''/** 局部精炼：相邻两段若合并后匹配显著更优则合并；过宽段若拆分显著更优则拆分。 */'''
new = '''/** 把分段灰度块按 -angle 旋转到水平，重新量墨盒并归一化。
 *  返回 { grid, aspect, inkH }：去旋转后的归一化网格、墨盒宽高比、墨高（px）。 */
function derotatePatch(gray, width, height, seg, angleDeg) {
  const rad = -angleDeg * Math.PI / 180;
  const cos = Math.cos(rad), sin = Math.sin(rad);
  const cx = (seg.x0 + seg.x1) / 2, cy = (seg.y0 + seg.y1) / 2;
  const pw = seg.x1 - seg.x0 + 1, ph = seg.y1 - seg.y0 + 1;
  const size = Math.ceil(Math.hypot(pw, ph)) + 4;
  const half = size / 2;
  const patch = new Float32Array(size * size);
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const dx = x - half, dy = y - half;
      const sx = cx + cos * dx - sin * dy;
      const sy = cy + sin * dx + cos * dy;
      patch[y * size + x] = sampleBilinear(gray, width, height, sx, sy, 255);
    }
  }
  // 墨盒（阈值映射同 normalizeRegion）
  let x0 = size, x1 = -1, y0 = size, y1 = -1;
  const inkAt = (x, y) => Math.max(0, Math.min(1, (190 - patch[y * size + x]) / 170));
  for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
    if (inkAt(x, y) > 0.35) {
      if (x < x0) x0 = x; if (x > x1) x1 = x;
      if (y < y0) y0 = y; if (y > y1) y1 = y;
    }
  }
  if (x1 < 0) return { grid: new Float32Array(GW * GH), aspect: 1, inkH: ph };
  const bw = x1 - x0 + 1, bh = y1 - y0 + 1;
  const grid = new Float32Array(GW * GH);
  for (let gy = 0; gy < GH; gy++) {
    for (let gx = 0; gx < GW; gx++) {
      let v = 0;
      for (let sy = 0.25; sy < 1; sy += 0.5) {
        for (let sx = 0.25; sx < 1; sx += 0.5) {
          const px = Math.min(size - 1, Math.round(x0 + ((gx + sx) * bw) / GW));
          const py = Math.min(size - 1, Math.round(y0 + ((gy + sy) * bh) / GH));
          v += inkAt(px, py);
        }
      }
      grid[gy * GW + gx] = v / 4;
    }
  }
  return { grid, aspect: bw / bh, inkH: bh };
}

/** 局部精炼：相邻两段若合并后匹配显著更优则合并；过宽段若拆分显著更优则拆分。 */'''
assert old in src; src = src.replace(old, new)

# 5) 引入 sampleBilinear
src = src.replace("import { toGray, binarize } from './image.js';",
                  "import { toGray, binarize, sampleBilinear } from './image.js';")
open(p,'w').write(src)
print('ok')
EOF
