{"cmd": "python3 - <<'EOF'
p = 'core/chars.js'
src = open(p).read()

# 模板缓存补充 0° 字高映射
src = src.replace('''let TPL_CACHE = null;
/** 解码离线生成的 字符x角度 模板（惰性缓存）。 */
function templates() {
  if (TPL_CACHE) return TPL_CACHE;
  TPL_CACHE = [];''',
'''let TPL_CACHE = null;
let CHAR_H0 = null;
/** 解码离线生成的 字符x角度 模板（惰性缓存）。 */
function templates() {
  if (TPL_CACHE) return TPL_CACHE;
  TPL_CACHE = [];
  CHAR_H0 = {};''')
src = src.replace('''      TPL_CACHE.push({ ch, angle: t.a, grid, ink, aspect: t.r, hFrac: t.h, dt: distanceTransform(grid, GW, GH) });''',
'''      TPL_CACHE.push({ ch, angle: t.a, grid, ink, aspect: t.r, hFrac: t.h, dt: distanceTransform(grid, GW, GH) });
      if (t.a === 0) CHAR_H0[ch] = t.h;''')

# 重写第二遍：多角度匹配（含行高自校准）+ 去旋转字高决胜
old = '''  // 第二遍：先去旋转（用第一遍估计的角度），再在 0° 模板族上重打分。
  // 去旋转后字高测量无旋转膨胀，大小写可可靠区分；行高由等宽字距反推并自校准。
  const span = segs[segs.length - 1].x1 - segs[0].x0 + 1;
  const baseLineH = (span / segs.length) * LINE_OVER_ADVANCE;
  const prepared = segs.map(s => {
    const grid0 = normalizeRegion(gray, width, height, s.x0, s.y0, s.x1, s.y1);
    const m1 = matchSegment(grid0, (s.x1 - s.x0 + 1) / (s.y1 - s.y0 + 1), null);
    return derotatePatch(gray, width, height, s, m1.best.angle);
  });
  let bestPass = null;
  for (const scale of [0.88, 0.94, 1.0, 1.06, 1.12]) {
    const lineH = baseLineH * scale;
    let total = 0;
    const pass = prepared.map(p => {
      const m = matchSegment(p.grid, p.aspect, p.inkH / lineH, true);
      total += m.best.score;
      return m;
    });
    if (!bestPass || total < bestPass.total) bestPass = { total, pass };
  }
  segs.forEach((s, i) => {
    const m = bestPass.pass[i];
    s.ch = m.best.ch;
    s.cost = m.best.score;
    s.conf = Math.max(0, (m.second.score - m.best.score) / Math.max(0.05, m.second.score));
  });'''
new = '''  // 第二遍：多角度匹配（行高由等宽字距反推并自校准）；
  // 比分接近时（多为同形大小写对），用去旋转后的绝对字高做决胜。
  const span = segs[segs.length - 1].x1 - segs[0].x0 + 1;
  const baseLineH = (span / segs.length) * LINE_OVER_ADVANCE;
  const grids = segs.map(s => normalizeRegion(gray, width, height, s.x0, s.y0, s.x1, s.y1));
  let bestPass = null;
  for (const scale of [0.88, 0.94, 1.0, 1.06, 1.12]) {
    const lineH = baseLineH * scale;
    let total = 0;
    const pass = segs.map((s, i) => {
      const segHFrac = (s.y1 - s.y0 + 1) / lineH;
      const m = matchSegment(grids[i], (s.x1 - s.x0 + 1) / (s.y1 - s.y0 + 1), segHFrac);
      total += m.best.score;
      return m;
    });
    if (!bestPass || total < bestPass.total) bestPass = { total, pass, lineH };
  }
  segs.forEach((s, i) => {
    const m = bestPass.pass[i];
    let ch = m.best.ch;
    // 决胜：前两名接近时，用去旋转字高 vs 0° 模板字高重新裁决
    if (m.second.score - m.best.score < 0.08 && CHAR_H0[ch] !== undefined && CHAR_H0[m.second.ch] !== undefined
        && Math.abs(CHAR_H0[ch] - CHAR_H0[m.second.ch]) > 0.04) {
      const p = derotatePatch(gray, width, height, s, m.best.angle ?? 0);
      const hFracD = p.inkH / bestPass.lineH;
      const penBest = Math.abs(hFracD - CHAR_H0[ch]);
      const penSecond = Math.abs(hFracD - CHAR_H0[m.second.ch]);
      if (penSecond + 0.06 < penBest) ch = m.second.ch;
    }
    s.ch = ch;
    s.cost = m.best.score;
    s.conf = Math.max(0, (m.second.score - m.best.score) / Math.max(0.05, m.second.score));
  });'''
assert old in src; src = src.replace(old, new)
open(p,'w').write(src)
print('ok')
