{"cmd": "python3 - <<'EOF'
p = 'core/chars.js'
src = open(p).read()

# matchSegment 返回 perChar 明细
src = src.replace('''  return { best: { ...best, angle: perCharAngle.get(best.ch) }, second };
}''',
'''  return { best: { ...best, angle: perCharAngle.get(best.ch) }, second, perChar };
}''')

# 第二遍：主匹配 + 去旋转字高作为统一加分项
old = '''  segs.forEach((s, i) => {
    const m = bestPass.pass[i];
    let ch = m.best.ch;
    // 决胜：前两名接近时，用去旋转字高 vs 0° 模板字高重新裁决
    if (m.second.score - m.best.score < 0.15 && CHAR_H0[ch] !== undefined && CHAR_H0[m.second.ch] !== undefined
        && Math.abs(CHAR_H0[ch] - CHAR_H0[m.second.ch]) > 0.04) {
      const p = derotatePatch(gray, width, height, s, m.best.angle ?? 0);
      const hFracD = p.inkH / bestPass.lineH;
      const penBest = Math.abs(hFracD - CHAR_H0[ch]);
      const penSecond = Math.abs(hFracD - CHAR_H0[m.second.ch]);
      if (penSecond + 0.04 < penBest) ch = m.second.ch;
    }
    s.ch = ch;
    s.cost = m.best.score;
    s.conf = Math.max(0, (m.second.score - m.best.score) / Math.max(0.05, m.second.score));
  });'''
new = '''  segs.forEach((s, i) => {
    const m = bestPass.pass[i];
    // 去旋转字高作为统一加分项：对每个候选字符叠加 |实测字高比 - 0°模板字高比| 惩罚后重排名
    const p = derotatePatch(gray, width, height, s, m.best.angle ?? 0);
    const hFracD = p.inkH / bestPass.lineH;
    let best = null, second = null;
    for (const [cand, score0] of m.perChar) {
      const h0 = CHAR_H0[cand];
      const score = score0 + (h0 === undefined ? 0 : 1.2 * Math.max(0, Math.abs(hFracD - h0) - 0.05));
      if (!best || score < best.score) { second = best; best = { ch: cand, score }; }
      else if (!second || score < second.score) second = { ch: cand, score };
    }
    s.ch = best.ch;
    s.cost = best.score;
    s.conf = Math.max(0, (second.score - best.score) / Math.max(0.05, second.score));
  });'''
assert old in src; src = src.replace(old, new)
open(p,'w').write(src)
print('ok')
EOF
