p = 'core/chars.js'
src = open(p).read()

# 1) templates() 解码样本
old = '''let TPL_CACHE = null;
let CHAR_H0 = null;
/** 解码离线生成的 字符x角度 模板（惰性缓存）。 */
function templates() {
  if (TPL_CACHE) return TPL_CACHE;
  TPL_CACHE = [];
  CHAR_H0 = {};
  for (const ch of GEN_CHARSET) {
    for (const t of TEMPLATES[ch]) {
      const grid = new Float32Array(GW * GH);
      for (let i = 0; i < GW * GH; i++) grid[i] = parseInt(t.g[i], 16) / 15;
      let ink = 0;
      for (let i = 0; i < grid.length; i++) ink += grid[i];
      TPL_CACHE.push({ ch, angle: t.a, grid, ink, aspect: t.r, hFrac: t.h, dt: distanceTransform(grid, GW, GH) });
      if (t.a === 0) CHAR_H0[ch] = t.h;
    }
  }
  return TPL_CACHE;
}'''
new = '''let TPL_CACHE = null;
/** 解码离线生成的扭曲样本模板（惰性缓存）。 */
function templates() {
  if (TPL_CACHE) return TPL_CACHE;
  TPL_CACHE = [];
  for (const ch of GEN_CHARSET) {
    for (const t of TEMPLATES[ch]) {
      const grid = new Float32Array(GW * GH);
      for (let i = 0; i < GW * GH; i++) grid[i] = parseInt(t.g[i], 16) / 15;
      let ink = 0;
      for (let i = 0; i < grid.length; i++) ink += grid[i];
      TPL_CACHE.push({ ch, grid, ink, aspect: t.r, hFrac: t.h, dt: distanceTransform(grid, GW, GH) });
    }
  }
  return TPL_CACHE;
}'''
assert old in src; src = src.replace(old, new)

# 2) matchSegment 去掉角度逻辑
src = src.replace('''function matchSegment(grid, segAspect, segHFrac = null, angle0Only = false) {''',
                  '''function matchSegment(grid, segAspect, segHFrac = null) {''')
src = src.replace('''  const perChar = new Map();
  const perCharAngle = new Map();
  for (const t of templates()) {
    if (angle0Only && Math.abs(t.angle) > 3) continue;
    let d1 = 0, d2 = 0;''',
'''  const perChar = new Map();
  for (const t of templates()) {
    let d1 = 0, d2 = 0;''')
src = src.replace('''    const cur = perChar.get(t.ch);
    if (cur === undefined || score < cur) { perChar.set(t.ch, score); perCharAngle.set(t.ch, t.angle); }
  }
  let best = null, second = null;
  for (const [ch, score] of perChar) {
    if (!best || score < best.score) { second = best; best = { ch, score }; }
    else if (!second || score < second.score) second = { ch, score };
  }
  return { best: { ...best, angle: perCharAngle.get(best.ch) }, second, perChar };
}''',
'''    const cur = perChar.get(t.ch);
    if (cur === undefined || score < cur) perChar.set(t.ch, score);
  }
  let best = null, second = null;
  for (const [ch, score] of perChar) {
    if (!best || score < best.score) { second = best; best = { ch, score }; }
    else if (!second || score < second.score) second = { ch, score };
  }
  return { best, second, perChar };
}''')

# 3) 第二遍：行高自校准 + 样本匹配（无去旋转）
old_start = src.index('''  // 第二遍：多角度匹配（行高由等宽字距反推并自校准）；''')
old_end = src.index('''  const text = segs.map(s => s.ch).join('');''')
new_pass = '''  // 第二遍：样本模板匹配（行高由等宽字距反推并自校准 ±12%）。
  const span = segs[segs.length - 1].x1 - segs[0].x0 + 1;
  const baseLineH = (span / segs.length) * LINE_OVER_ADVANCE;
  const grids = segs.map(s => normalizeRegion(gray, width, height, s.x0, s.y0, s.x1, s.y1));
  let bestPass = null;
  for (const scale of [0.88, 0.94, 1.0, 1.06, 1.12]) {
    const lineH = baseLineH * scale;
    let total = 0;
    const pass = segs.map((s, i) => {
      const segHFrac = (s.y1 - s.y0 + 1) / lineH;
      const m = matchSegment(grids[i], (s.x1 - s.x0 + 1) / (s.y1 - s.y0 + 1), segHFrac);
      total += m.best.score;
      return m;
    });
    if (!bestPass || total < bestPass.total) bestPass = { total, pass };
  }
  segs.forEach((s, i) => {
    const m = bestPass.pass[i];
    s.ch = m.best.ch;
    s.cost = m.best.score;
    s.conf = Math.max(0, (m.second.score - m.best.score) / Math.max(0.05, m.second.score));
  });
'''
src = src[:old_start] + new_pass + src[old_end:]

# 4) 删除 derotatePatch（不再使用）
dstart = src.index('/** 把分段灰度块按 -angle 旋转到水平')
dend = src.index('/** 局部精炼：')
src = src[:dstart] + src[dend:]
src = src.replace("import { toGray, binarize, sampleBilinear } from './image.js';",
                  "import { toGray, binarize } from './image.js';")
src = src.replace(", derotatePatch }", " }")
open(p,'w').write(src)
print('ok')
EOF
