old_end = src.index('''  const text = segs.map(s => s.ch).join('');''')
new_pass = '''  // 第二遍：样本模板匹配（行高由等宽字距反推并自校准 ±12%）。
  const span = segs[segs.length - 1].x1 - segs[0].x0 + 1;
  const baseLineH = (span / segs.length) * LINE_OVER_ADVANCE;
  const grids = segs.map(s => normalizeRegion(gray, width, height, s.x0, s.y0, s.x1, s.y1));
  let bestPass = null;
  for (const scale of [0.88, 0.94, 1.0, 1.06, 1.12]) {
    const lineH = baseLineH * scale;
    let total = 0;
    const pass = segs.map((s, i) => {
      const segHFrac = (s.y1 - s.y0 + 1) / lineH;
      const m = matchSegment(grids[i], (s.x1 - s.x0 + 1) / (s.y1 - s.y0 + 1), segHFrac);
      total += m.best.score;
      return m;
    });
    if (!bestPass || total < bestPass.total) bestPass = { total, pass };
  }
  segs.forEach((s, i) => {
    const m = bestPass.pass[i];
    s.ch = m.best.ch;
    s.cost = m.best.score;
    s.conf = Math.max(0, (m.second.score - m.best.score) / Math.max(0.05, m.second.score));
  });
'''
