{"cmd": "python3 - <<'EOF'
p = 'core/chars.js'
src = open(p).read()
old = '''  // 基线估计：各分段底边的中位数（降部字符为少数，中位数稳健）
  const bottoms = segs.map(s => s.y1).sort((a, b) => a - b);
  const baseline = bottoms[Math.floor(bottoms.length / 2)];'''
new = '''  // 基线估计：底边的最大聚类点（降部字符在基线之下，属少数派）
  let baseline = segs[0].y1, bestCnt = -1;
  for (const s of segs) {
    let cnt = 0;
    for (const t of segs) if (Math.abs(t.y1 - s.y1) <= 3) cnt++;
    // 并列时取更靠上的（基线在降部之上）
    if (cnt > bestCnt || (cnt === bestCnt && s.y1 < baseline)) { bestCnt = cnt; baseline = s.y1; }
  }'''
assert old in src; src = src.replace(old, new)
open(p,'w').write(src)
print('ok')
EOF
node /tmp/cal.mjs 2>&1 | head -4", "yield_time_ms": 240000}

