p = 'core/chars.js'
src = open(p).read()
# DP 分段：y 搜索不再夹在 [rTop, rBot]，改全高（行墨量>=2 规则已抗噪）
old = '''      // 高度按"行墨量>=2"测量：排除单像素噪点行，保留边缘细升部（b/d 的竖笔）
      let y0 = rBot, y1 = rTop;
      for (let y = rTop; y <= rBot; y++) {
        let rowCnt = 0;
        for (let x = xa; x <= xb; x++) if (bits[y * width + x]) rowCnt++;
        if (rowCnt >= 2) { if (y < y0) y0 = y; if (y > y1) y1 = y; }
      }
      if (y0 > y1) { y0 = rTop; y1 = rBot; }
      y0 = Math.max(rTop, y0 - 1); y1 = Math.min(rBot, y1 + 1);'''
new = '''      // 高度按"行墨量>=2"全高测量：排除单像素噪点行；
      // 不能用 [rTop, rBot] 夹取——行投影阈值会切掉降部（q/p/g/y 的细尾巴）
      let y0 = height, y1 = -1;
      for (let y = 0; y < height; y++) {
        let rowCnt = 0;
        for (let x = xa; x <= xb; x++) if (bits[y * width + x]) rowCnt++;
        if (rowCnt >= 2) { if (y < y0) y0 = y; if (y > y1) y1 = y; }
      }
      if (y0 > y1) { y0 = rTop; y1 = rBot; }
      y0 = Math.max(0, y0 - 1); y1 = Math.min(height - 1, y1 + 1);'''
