import { test } from 'node:test';
import assert from 'node:assert/strict';
import { locateGap } from '../core/index.js';
import { loadManifest, loadRaw } from './helpers.js';

const MAX_ERR_PX = 2.5;        // 单张定位容差（亚像素级要求下的硬指标）
const MAX_MEAN_ERR_PX = 1.0;   // 平均误差须达到亚像素级
const MIN_SUCCESS_RATE = 0.95;

test('缺口定位：亚像素精度（模糊边缘/渐变/多伪缺口下）', () => {
  const man = loadManifest();
  let solved = 0, skipped = 0;
  const errs = [];
  const failures = [];
  for (const entry of man.slider) {
    const r = locateGap(loadRaw('slider', entry));
    if (r.action === 'solve') {
      const err = Math.abs(r.x - entry.gapX);
      errs.push(err);
      if (err <= MAX_ERR_PX) solved++;
      else failures.push({ file: entry.file, expected: entry.gapX, got: r.x });
    } else {
      skipped++; // 允许跳过，不计入失败
    }
  }
  const mean = errs.reduce((a, b) => a + b, 0) / Math.max(1, errs.length);
  const rate = solved / man.slider.length;
  assert.equal(failures.length, 0, `存在超差定位: ${JSON.stringify(failures)}`);
  assert.ok(mean <= MAX_MEAN_ERR_PX, `平均误差 ${mean.toFixed(2)}px 未达亚像素级`);
  assert.ok(rate >= MIN_SUCCESS_RATE,
    `成功率 ${(rate * 100).toFixed(1)}% < ${MIN_SUCCESS_RATE * 100}%（跳过 ${skipped} 张）`);
});

test('缺口定位：无边缘的纯色图应输出 skip 而非硬猜', () => {
  const img = { width: 100, height: 60, data: new Uint8ClampedArray(100 * 60 * 4).fill(128) };
  const r = locateGap(img);
  assert.equal(r.action, 'skip');
});
EOF
cat > tests/chars.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { recognizeChars } from '../core/index.js';
import { loadManifest, loadRaw } from './helpers.js';

const MIN_SOLVE_RATE = 0.7;      // 至少 70% 输出识别结果（其余可跳过）
const MIN_SOLVE_PRECISION = 0.95; // 输出结果的准确率（不硬猜）
const MIN_SKIP_ERROR_RATE = 0.6;  // 被跳过的那批确实大概率会错

function evaluate() {
  const man = loadManifest();
  let correct = 0, wrong = 0, skipped = 0, skipWouldBeWrong = 0;
  const errors = [];
  for (const entry of man.chars) {
    const r = recognizeChars(loadRaw('chars', entry));
    if (r.action === 'solve') {
      if (r.text === entry.text) correct++;
      else { wrong++; errors.push({ file: entry.file, expected: entry.text, got: r.text }); }
    } else {
      skipped++;
      if (r.text !== entry.text) skipWouldBeWrong++; // 若硬猜会错
    }
  }
  return { total: man.chars.length, correct, wrong, skipped, skipWouldBeWrong, errors };
}

test('字符识别：升级 fixture 下高准确率且不硬猜', () => {
  const r = evaluate();
  const solveRate = (r.correct + r.wrong) / r.total;
  const precision = r.correct / Math.max(1, r.correct + r.wrong);
  assert.ok(r.wrong <= 1, `硬猜错误过多: ${JSON.stringify(r.errors)}`);
  assert.ok(solveRate >= MIN_SOLVE_RATE, `识别率 ${(solveRate * 100).toFixed(1)}% < ${MIN_SOLVE_RATE * 100}%`);
  assert.ok(precision >= MIN_SOLVE_PRECISION,
    `输出准确率 ${(precision * 100).toFixed(1)}% < ${MIN_SOLVE_PRECISION * 100}%`);
});

test('字符识别：置信度校准——跳过的确实大概率会错', () => {
  const r = evaluate();
  assert.ok(r.skipped > 0, '应有低置信度跳过样本');
  const skipErrRate = r.skipWouldBeWrong / r.skipped;
  assert.ok(skipErrRate >= MIN_SKIP_ERROR_RATE,
    `跳过样本的错误率 ${(skipErrRate * 100).toFixed(1)}% < ${MIN_SKIP_ERROR_RATE * 100}%（校准失效）`);
});

test('字符识别：空白图输出 skip', () => {
  const img = { width: 120, height: 50, data: new Uint8ClampedArray(120 * 50 * 4).fill(245) };
  const r = recognizeChars(img);
  assert.equal(r.action, 'skip');
});

test('字符识别：纯噪点图低置信度时 skip 而非硬猜', () => {
  const img = { width: 120, height: 50, data: new Uint8ClampedArray(120 * 50 * 4) };
  let seed = 42;
  for (let i = 0; i < img.data.length; i += 4) {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    const v = seed % 256;
    img.data[i] = img.data[i + 1] = img.data[i + 2] = v;
    img.data[i + 3] = 255;
  }
  const r = recognizeChars(img);
  if (r.action === 'solve') {
    assert.ok(r.confidence >= 0.15, '低置信度不应输出 solve');
  }
});
